    28	    @Override
    29	    public PaymentTerms terms(PaymentContext context) {
    30	        BigDecimal total = context.orderTotal();
    31	        int n = context.installments();
    32	        if (n <= MAX_INTEREST_FREE) {
    33	            return new PaymentTerms(total, total.divide(BigDecimal.valueOf(n), 2, Money.ROUNDING));
    34	        }
    36	        MathContext mc = MathContext.DECIMAL128;
    37	        BigDecimal discountFactor = BigDecimal.ONE.divide(BigDecimal.ONE.add(MONTHLY_RATE).pow(n), mc);
    38	        BigDecimal installment = Money.round(
    39	                total.multiply(MONTHLY_RATE).divide(BigDecimal.ONE.subtract(discountFactor), mc));
    40	        return new PaymentTerms(installment.multiply(BigDecimal.valueOf(n)), installment);
    41	    }
    42	}
